    "subTest": "WRITING",
    "taskType": "WRITING_LETTER",
    "profession": "DIETETICS",
    "slug": "wri-dietetics-referral-to-the-community-team-nutrition-at-the-end-of-life",
    "title": "Dietetics — Referral to the community team: nutrition at the end of life",
    "prompt": "Using the case notes, write a letter as instructed. Write 180–200 words. Select only the information that is relevant to the reader and to the purpose of the letter.",
    "difficulty": "CORE",
    "topicTag": "palliative-nutrition",
