    "subTest": "WRITING",
    "taskType": "WRITING_LETTER",
    "profession": "DIETETICS",
    "slug": "wri-dietetics-referral-to-the-paediatric-dietetic-team-a-child-with-faltering-growth",
    "title": "Dietetics — Referral to the paediatric dietetic team: a child with faltering growth",
    "prompt": "Using the case notes, write a letter as instructed. Write 180–200 words. Select only the information that is relevant to the reader and to the purpose of the letter.",
    "difficulty": "CORE",
